/** Fictional, independently authored situations. None is a relabelled legacy lesson.
 * Compact scene notation stores the actual information, not model prompts. The
 * formatter supplies spoken transitions and task layouts; all keys are explicit.
 * These are AI-assisted practice materials, not official IELTS examination papers.
 */
interface Fact { label: string; answer: string; unit?: string }
interface Scene { title: string; topic: string; situation: string; extension: string; facts: Fact[]; level: Cefr; part: 1 | 2 | 3 | 4; layout: number; serial: number }
const generatedAt = "2026-10-08T00:00:00.000Z";
const accents: DialogueLine["accent"][] = ["british", "australian", "american"];
const names = ["Clara", "Imran", "Sophie", "Ben", "Leila", "Harvey", "Naomi", "Owen", "Zara", "Miles", "Rosa", "Theo", "Ava", "Dylan", "Mina", "Leo"];
function parse(rows: string[], level: Cefr, part: Scene["part"], offset: number): Scene[] {
  return rows.map((row, i) => {
    const [title, topic, situation, extension, data] = row.split("|");
    const facts = data!.split(";").map((s) => { const [label, answer] = s.split("="); const [key, unit] = answer!.split("~"); return { label: label!.trim(), answer: key!.trim(), unit: unit?.trim() }; });
    if (facts.length !== 10 || facts.some((f) => !f.label || !f.answer)) throw new Error(`Listening scene requires ten explicit facts: ${title}`);
    return { title: title!, topic: topic!, situation: situation!, extension: extension!, facts, level, part, layout: i % 8, serial: offset + i };
  });
}
